<?php use App\Helpers\{View,Csrf};?><div class="admin-head"><div><span class="eyebrow">VENTAS</span><h1>Pedidos</h1></div><a href="/admin">← Panel</a></div><div class="table-wrap"><table><thead><tr><th>#</th><th>Cliente</th><th>Entrega</th><th>Fecha</th><th>Subtotal</th><th>Descuento</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><b>#<?=$o['id']?></b></td><td><?=View::e($o['first_name'].' '.$o['last_name'])?><small>@<?=View::e($o['username'])?></small></td><td><?=($o['delivery_method']??'RETIRO')==='DOMICILIO'?'Domicilio':'Retiro'?></td><td><?=date('d/m/Y H:i',strtotime($o['created_at']))?></td><td>$<?=number_format($o['subtotal'],2)?></td><td>$<?=number_format($o['discount'],2)?></td><td><b>$<?=number_format($o['total'],2)?></b></td><td><form class="statusform" method="post" action="/admin/orders/<?=$o['id']?>/status"><?=Csrf::field()?><select name="status_id" onchange="this.form.submit()"><?php foreach($o['available_statuses'] as $s):?><option value="<?=$s['id']?>" <?=$s['name']===$o['status_name']?'selected':''?>><?=View::e($s['name'])?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></tbody></table></div>
